const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const money=n=>new Intl.NumberFormat('it-IT',{style:'currency',currency:'EUR'}).format(n);const num=n=>new Intl.NumberFormat('it-IT').format(n);let mode='demo';let repo,engine,rows=[],stockHistory=[],chartProduct='',page=location.hash.slice(1)||'dashboard',search='',category='',brandFilter='',promoOnly=false,orderFilter='',status='demo',syncError='',installPrompt,updateWorker;
