function trialDaysLeft(e=repo?.entitlement){return isTrial(e)?Math.max(0,Math.ceil(trialRemaining(e)/86400000)):0;}
function trialDaysText(e=repo?.entitlement){const days=trialDaysLeft(e);return days===1?'1 giorno rimasto':days+' giorni rimasti';}
function subscriptionOffer(compact=false){const e=repo?.entitlement;if(mode!=='cloud'||!e||!isTrial(e))return '';return `<div class="subscription-offer ${compact?'compact':''}"><strong>Prezzo di lancio · 3,90 €/mese</strong><p class="hint">Hai ancora ${esc(trialDaysText(e))}. Puoi abbonarti subito e mantenere 3,90 €/mese finché l’abbonamento resta attivo.</p><button type="button" class="primary subscribe-now">Abbonati ora · 3,90 €/mese</button></div>`;}
async function openSubscriptionCheckout(){if(mode!=='cloud'||!repo?.customer||!auth.currentSession())return toast('Accedi al tuo account per abbonarti.');if(!config.paymentLink)return toast('Pagamento non configurato.');const buttons=[...document.querySelectorAll('.subscribe-now')];buttons.forEach(b=>b.disabled=true);try{const checkout=await cloud.prepareCheckout(repo.customer),url=new URL(config.paymentLink);url.searchParams.set('client_reference_id',checkout.reference);location.assign(url.href);}catch(e){toast(e.message);buttons.forEach(b=>b.disabled=false);}}
function subscriptionIntent(){const value=Number(localStorage.getItem('sg:subscribe-intent'));if(!Number.isFinite(value)||Date.now()-value>86400000){localStorage.removeItem('sg:subscribe-intent');return false;}return true;}
function beginSubscription(){if(mode==='cloud'&&repo?.customer&&auth.currentSession())return openSubscriptionCheckout();localStorage.setItem('sg:subscribe-intent',String(Date.now()));if(auth.currentSession())return chooseTenant();activationScreen();}
function subscriptionStatusStrip(){if(!config.paymentLink)return '';const e=repo?.entitlement;if(mode==='cloud'&&e&&isTrial(e)){const days=trialDaysLeft(e),urgent=days<=3;return `<div class="subscription-strip ${urgent?'urgent':''}"><span><strong>${days===0?'Prova terminata':urgent?'La prova sta per terminare':'Prova gratuita attiva'}</strong> · ${esc(trialDaysText(e))}</span><span class="subscription-strip-price">Prezzo di lancio <b>3,90 €/mese</b></span><button type="button" class="primary subscribe-now">Abbonati ora</button></div>`;}if(mode==='demo'&&config.unifiedMode)return '<div class="subscription-strip demo-offer"><span><strong>Gestionale completo</strong> · 14 giorni gratis disponibili</span><span class="subscription-strip-price">Prezzo di lancio <b>3,90 €/mese</b></span><button type="button" class="primary subscribe-demo">Scopri e abbonati</button></div>';return '';}
function subscriptionHomeCard(){if(!config.paymentLink)return '';const e=repo?.entitlement,isCloudTrial=mode==='cloud'&&e&&isTrial(e),isDemoOffer=mode==='demo'&&config.unifiedMode;if(!isCloudTrial&&!isDemoOffer)return '';const buttonClass=isCloudTrial?'subscribe-now':'subscribe-demo',days=isCloudTrial?trialDaysText(e):'14 giorni gratuiti disponibili';return `<section class="card subscription-card"><div class="subscription-card-copy"><span class="eyebrow">Prezzo di lancio</span><h2>Passa alla versione completa</h2><p>${isCloudTrial?'La prova continua normalmente, ma puoi abbonarti già adesso.':'Puoi iniziare con la prova gratuita e decidere quando passare alla versione completa.'}</p><ul class="subscription-benefits"><li>I tuoi dati restano nel tuo archivio</li><li>Prezzo di 3,90 €/mese mantenuto finché l’abbonamento resta attivo</li><li>Nessuna attesa: puoi abbonarti anche prima della fine della prova</li></ul><span class="subscription-trial-note">${esc(days)}</span></div><div class="subscription-card-action"><div class="subscription-price"><strong>3,90 €</strong><span>/ mese</span></div><button type="button" class="primary ${buttonClass}">Abbonati ora</button><small>Pagamento sicuro con Stripe</small></div></section>`;}
function showSubscriptionDetails(automatic=false){if(!config.paymentLink)return toast('Pagamento non configurato.');const e=repo?.entitlement,isCloudTrial=mode==='cloud'&&e&&isTrial(e),days=isCloudTrial?trialDaysLeft(e):14,buttonClass=isCloudTrial?'subscribe-now':'subscribe-demo',remaining=isCloudTrial?trialDaysText(e):'14 giorni gratuiti disponibili',urgent=isCloudTrial&&days<=3;showDialog(automatic?'Continua con Gestionale & Inventario':'Abbonamento',`<section class="subscription-reminder ${urgent?'urgent':''}"><span class="subscription-kicker">${urgent?'La prova sta per terminare':'Prezzo di lancio'}</span><div class="subscription-price"><strong>3,90 €</strong><span>/ mese</span></div><p><strong>${esc(remaining)}</strong>. ${isCloudTrial?'Puoi continuare la prova oppure abbonarti subito.':'Registrati, prova il gestionale e passa alla versione completa quando vuoi.'}</p><p>Se ti sta già servendo, puoi bloccare il prezzo di lancio di <strong>3,90 €/mese</strong> finché mantieni attivo l’abbonamento.</p><div class="subscription-reminder-actions"><button type="button" class="primary ${buttonClass}">Abbonati ora · 3,90 €/mese</button>${automatic?'<button type="button" id="trial-reminder-later">Continua la prova</button>':''}</div></section>`);bindSubscriptionActions($('#modal'));if($('#trial-reminder-later'))$('#trial-reminder-later').onclick=()=>$('#modal').close();}
function maybeShowSubscriptionReminder(){const e=repo?.entitlement;if(mode!=='cloud'||!e||!isTrial(e)||!trialActive(e)||!config.paymentLink||subscriptionIntent()||$('#modal')?.open)return;const elapsed=Math.min(14,Math.max(1,15-trialDaysLeft(e))),milestones=[1,3,7,11,13],milestone=milestones.filter(day=>elapsed>=day).at(-1)||0;if(!milestone)return;const key='sg:trial-reminder:'+repo.customer+':'+e.trial.expires_at,seen=Number(localStorage.getItem(key)||0);if(seen>=milestone)return;localStorage.setItem(key,String(milestone));showSubscriptionDetails(true);}
function bindSubscriptionActions(root=document){root?.querySelectorAll?.('.subscribe-now').forEach(b=>b.onclick=openSubscriptionCheckout);root?.querySelectorAll?.('.subscribe-demo').forEach(b=>b.onclick=beginSubscription);}


function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4500);}function name(id){return rows.find(r=>r.id===id)?.payload.name||'—';}function items(kind){return enabled(kind==='brands'?'categories':kind)?rows.filter(r=>r.kind===kind):[];}function payloads(kind){return items(kind).map(r=>({...r.payload,id:r.id}));}function enabled(id){return repo?.entitlement?.modules.includes(id);}function setting(){return repo.entitlement.customer.config||{};}function price(p){return p.promo??salePrice(p,setting());}function stockPill(p){return `<span class="pill ${p.stock===0?'red':p.stock<=p.threshold?'warn':''}">${p.stock===0?'Esaurito':p.stock<=p.threshold?'Da riordinare':'Disponibile'}</span>`;}function validLicense(){const e=repo?.entitlement;if(isTrial(e))return e.customer.active!==false&&e.license.active&&trialActive(e);return e&&(mode==='demo'||auth.currentSession()?.expires_at>Date.now())&&e.customer.active!==false&&canOffline(e,Date.now(),config.offlineGraceMs);}
