function hydrateProductImages(){if(mode!=='cloud')return;document.querySelectorAll('img').forEach(i=>{const source=i.getAttribute('src');const productPath=cloud.productImagePath(source),brandingPath=cloud.brandingImagePath(source);if(!productPath&&!brandingPath)return;i.dataset.cloudImage=source;i.src='/simplex-gestionale-demo/assets/icon-192.png';const resolve=brandingPath?cloud.signedBrandingImage(source):cloud.signedProductImage(source);resolve.then(url=>{if(i.isConnected&&i.dataset.cloudImage===source)i.src=url;}).catch(e=>{i.title=(brandingPath?'Logo':'Foto')+' non disponibile: '+e.message;});});}

